const StateIllustrations = () => (
  <div style={{ display: 'flex', gap: 28, alignItems: 'center', flexWrap: 'wrap' }}>
    <SpotIllustration variant="empty" size={132} />
    <SpotIllustration variant="success" size={132} />
    <SpotIllustration variant="error" size={132} />
  </div>
);

const Mark = () => (
  <div style={{ display: 'flex', gap: 16, alignItems: 'center' }}>
    <CopilotMark size={22} />
    <CopilotMark size={26} />
    <CopilotMark size={32} />
  </div>
);

const Insight = () => (
  <div style={{ maxWidth: 360 }}>
    <CopilotInsight text="Pairs with Okta to map cloud access back to real identities." />
  </div>
);

const RecommendationPanel = () => (
  <div style={{ maxWidth: 720 }}>
    <SetupCopilotPanel items={INTEGRATIONS} onOpen={() => {}} />
  </div>
);

const Buttons = () => (
  <div style={{ display: 'flex', gap: 12, flexWrap: 'wrap', alignItems: 'center' }}>
    <button className="btn btn-primary">Primary</button>
    <button className="btn btn-brand">
      <Sparkles size={14} /> Brand
    </button>
    <button className="btn btn-ghost">Ghost</button>
    <button className="btn btn-danger">Danger</button>
  </div>
);

const Fields = () => (
  <div style={{ display: 'flex', flexDirection: 'column', gap: 12, maxWidth: 320 }}>
    <input className="field" placeholder="Search integrations…" />
    <input className="field" defaultValue="us-east-1" />
  </div>
);

const ColorTokens = () => (
  <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(150px, 1fr))', gap: 12 }}>
    {TOKENS.map((t) => (
      <div key={t} style={{ display: 'flex', alignItems: 'center', gap: 10 }}>
        <span
          style={{
            width: 34,
            height: 34,
            borderRadius: 9,
            background: `var(${t})`,
            border: '1px solid var(--border)',
            flexShrink: 0,
          }}
        />
        <code style={{ fontSize: 11, color: 'var(--text-2)' }}>{t}</code>
      </div>
    ))}
  </div>
);

const Recommended = () => <IntegrationCard
    onOpen={() => {}}
    integration={withStatus('not_connected', { recommended: true })} />;

const AllStates = () => (
  <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(300px, 1fr))', gap: 16 }}>
    {ALL.map((s) => (
      <IntegrationCard key={s} integration={withStatus(s)} onOpen={() => {}} />
    ))}
  </div>
);

const Gallery = () => (
  <div style={{ display: 'flex', gap: 14, flexWrap: 'wrap' }}>
    {SAMPLES.map((s) => (
      <LogoTile key={s.mono} mono={s.mono} color={s.color} />
    ))}
  </div>
);

const Sizes = () => (
  <div style={{ display: 'flex', gap: 14, alignItems: 'center' }}>
    {[28, 36, 44, 56, 72].map((sz) => (
      <LogoTile key={sz} mono="AW" color="#FF9900" size={sz} />
    ))}
  </div>
);

const AllBadges = () => (
  <div style={{ display: 'flex', flexDirection: 'column', gap: 12 }}>
    {ALL.map((s) => (
      <div key={s} style={{ display: 'flex', alignItems: 'center', gap: 14 }}>
        <StatusBadge status={s} />
        <code style={{ fontSize: 12, color: 'var(--text-3)' }}>{s}</code>
      </div>
    ))}
  </div>
);

const Dots = () => (
  <div style={{ display: 'flex', gap: 20, alignItems: 'center', flexWrap: 'wrap' }}>
    {ALL.map((s) => (
      <div key={s} style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 8 }}>
        <StatusDot status={s} size={12} />
        <code style={{ fontSize: 10, color: 'var(--text-3)' }}>{s}</code>
      </div>
    ))}
  </div>
);
